sp_widget.client_script:
api.controller = function($location, $anchorScroll, $timeout) {
  var c = this;

  c.scrollTo = function(sectionId) {
    // Allows Angular to update the hash and smoothly scroll to the section
    $location.hash(sectionId);
    $timeout(function() {
        $anchorScroll();
    }, 0);
  };
};

sp_widget.css:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

/* Full width background container */
.gn-page-background {
  /* Fallback */
  background-color: #eef0f8;
  /* Smoothly fades to white at the bottom */
  background: linear-gradient(to bottom, #eef0f8 0%, #eef0f8 85%, #ffffff 100%);
  min-height: 100vh;
  width: 100%;
  padding: 120px 0 72px 0; 
  font-family: "Segoe UI", Arial, sans-serif;
}
/* Centered content wrapper */
.gn-wrapper {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  color: #1a1a2e;
}

/* Header Styles */
.gn-header {
  text-align: center;
  margin-bottom: 40px;
}

.gn-header .gn-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  border: 1px solid #bfdbfe;
  border-radius: 20px;
  padding: 6px 16px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: #2563eb;
  text-transform: uppercase;
  margin-bottom: 20px;
}

.gn-header .gn-badge .dot {
  width: 7px;
  height: 7px;
  background: #2563eb;
  border-radius: 50%;
  display: inline-block;
}

.gn-header h1 {
  font-size: 48px;
  font-weight: 900;
  color: #1a1a2e;
  line-height: 1.2;
  margin-bottom: 12px;
  letter-spacing: -1px;
}

.gn-header h1 span { 
  color: #2fb8e0;
}

.gn-header p {
  font-size: 16px;
  color: #64748b;
  max-width: 600px;
  margin: 0 auto;
  line-height: 1.7;
}

.gn-dots {
  display: flex;
  gap: 8px;
  margin-bottom: 32px;
  justify-content: center;
}

.gn-dots span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #93c5fd;
  display: inline-block;
}

.gn-dots span:nth-child(2) { background: #2fb8e0; opacity: 1; }
.gn-dots span:nth-child(3) { background: #93c5fd; opacity: 0.6; }

/* Two-Column Layout */
.gn-layout {
  display: flex;
  gap: 32px;
  align-items: flex-start;
}

/* Left Table of Contents Sidebar */
.gn-toc-sidebar {
  width: 280px;
  flex-shrink: 0;
  position: sticky;
  top: 40px; 
  background: #ffffff;
  border-radius: 14px;
  padding: 30px;
  border: 1px solid #e8e6f5;
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.05);
}

.gn-toc-sidebar h3 {
  font-size: 16px;
  font-weight: 800;
  color: #1a1a2e;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid #f1f0fa;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.gn-toc-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.gn-toc-list a {
  color: #64748b;
  text-decoration: none;
  font-size: 14px;
  font-weight: 600;
  transition: color 0.2s ease;
  display: block;
}

.gn-toc-list a:hover {
  color: #2563eb;
}

/* Main Document Card */
.gn-card {
  flex: 1;
  min-width: 0;
  background: #ffffff;
  border-radius: 14px;
  padding: 50px 60px;
  border: 1px solid #e8e6f5;
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.05);
  margin-bottom: 30px;
}

@media (max-width: 960px) {
  .gn-layout { flex-direction: column; }
  .gn-toc-sidebar { width: 100%; position: static; }
  .gn-card { padding: 30px 20px; }
}

.gn-content .last-updated {
  font-size: 14px;
  color: #64748b;
  margin-bottom: 32px;
  font-style: italic;
}

.gn-content h2 {
  font-size: 18px;
  font-weight: 700;
  color: #2563eb;
  margin-top: 40px;
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid #f1f0fa;
  display: flex;
  align-items: center;
  gap: 10px;
}

.gn-content h2:first-child { margin-top: 0; }

.gn-content p {
  font-size: 15px;
  line-height: 1.8;
  color: #334155;
  margin-bottom: 16px;
}

.gn-content ul {
  margin-bottom: 20px;
  padding-left: 20px;
  list-style: none;
}

.gn-content ul li {
  font-size: 15px;
  line-height: 1.8;
  color: #334155;
  margin-bottom: 8px;
  position: relative;
}

.gn-content ul li::before {
  content: '•';
  color: #2fb8e0;
  font-weight: bold;
  font-size: 18px;
  position: absolute;
  left: -16px;
  top: -2px;
}

/* Modern Contact Section */
.gn-contact-section {
  margin-top: 60px;
  padding-top: 40px;
  border-top: 2px solid #f1f0fa;
}

.gn-contact-section h3 {
  font-size: 22px;
  font-weight: 800;
  color: #1a1a2e;
  text-align: center;
  margin-bottom: 8px;
}

.gn-contact-section p.subtitle {
  text-align: center;
  color: #64748b;
  font-size: 15px;
  margin-bottom: 32px;
}

.gn-contact-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

@media (max-width: 768px) {
  .gn-contact-cards { grid-template-columns: 1fr; }
}

.gn-contact-card-modern {
  background: #fcfcfd;
  border: 1px solid #e8e6f5;
  border-radius: 16px;
  padding: 28px 20px;
  text-align: center;
  transition: all 0.3s ease;
}

.gn-contact-card-modern:hover {
  background: #ffffff;
  box-shadow: 0 12px 28px rgba(37, 99, 235, 0.08);
  transform: translateY(-4px);
  border-color: #bfdbfe;
}

.gn-contact-icon {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}

/* Explicit sizing to prevent massive icons */
.gn-contact-icon svg {
  width: 24px !important;
  height: 24px !important;
  fill: currentColor;
}

.icon-phone { background-color: #fce7f3; color: #db2777; }
.icon-email { background-color: #e0f2fe; color: #3b82f6; }
.icon-website { background-color: #e0f2fe; color: #3b82f6; }

.gn-contact-card-modern h4 {
  font-size: 13px;
  font-weight: 700;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  margin-bottom: 10px;
}

.gn-contact-card-modern a, 
.gn-contact-card-modern span {
  font-size: 15px;
  color: #2563eb;
  font-weight: 700;
  text-decoration: none;
  display: block;
}

.gn-contact-card-modern a:hover {
  color: #2fb8e0;
}

/* Footer */
.gn-footer {
  text-align: center;
  margin-top: 40px;
  font-size: 12.5px;
  color: #94a3b8;
  line-height: 2;
}

.gn-footer a {
  color: #2563eb;
  text-decoration: none;
  font-weight: 600;
}

.gn-footer a:hover { color: #2fb8e0; }
